import{_ as l,C as r,o as e,c as i,a6 as n,b as s,w as o,a as d,E as g,al as c}from"./chunks/framework.BlDtR6jM.js";const D=JSON.parse('{"title":"区域设计：青炉镇与周边 (Area Design: Cyan Furnace Region)","description":"","frontmatter":{"readingTime":"5 min read"},"headers":[],"relativePath":"项目实践/JRPG/C_世界与探索/01_地图与关卡/区域设计/青炉镇区域.md","filePath":"项目实践/JRPG/C_世界与探索/01_地图与关卡/区域设计/青炉镇区域.md"}'),_={name:"项目实践/JRPG/C_世界与探索/01_地图与关卡/区域设计/青炉镇区域.md"};function u(h,t,f,E,y,C){const a=r("Mermaid");return e(),i("div",null,[t[1]||(t[1]=n('<h1 id="区域设计-青炉镇与周边-area-design-cyan-furnace-region" tabindex="-1">区域设计：青炉镇与周边 (Area Design: Cyan Furnace Region) <a class="header-anchor" href="#区域设计-青炉镇与周边-area-design-cyan-furnace-region" aria-label="Permalink to &quot;区域设计：青炉镇与周边 (Area Design: Cyan Furnace Region)&quot;">​</a></h1><h2 id="_1-区域概览-area-overview" tabindex="-1">1. 区域概览 (Area Overview) <a class="header-anchor" href="#_1-区域概览-area-overview" aria-label="Permalink to &quot;1. 区域概览 (Area Overview)&quot;">​</a></h2><p>本区域包含青炉镇及其周边的野外与迷宫节点。作为游戏初期的核心舞台，展现了<strong>东方神话</strong>与<strong>蒸汽工业</strong>融合的基调。</p><h3 id="_1-1-青炉镇-cyan-furnace-town" tabindex="-1">1.1 青炉镇 (Cyan Furnace Town) <a class="header-anchor" href="#_1-1-青炉镇-cyan-furnace-town" aria-label="Permalink to &quot;1.1 青炉镇 (Cyan Furnace Town)&quot;">​</a></h3><ul><li><strong>Scene_ID</strong>: <code>Town_CyanFurnace</code></li><li><strong>描述</strong>: 建立在古老青铜遗迹之上的边境小镇，镇中心有一座巨大的**&quot;青铜炼炉&quot;**，终日喷吐着白色蒸汽，为全镇提供动力。镇民习惯将机械义肢与传统武学结合。</li><li><strong>功能设施</strong>: <ul><li><strong>天机武馆 (Celestial Machine Dojo)</strong>: <em>[原演武堂]</em> 传授&quot;蒸汽动力拳法&quot;与基础械斗术的地方。馆长是一位装有机械臂的退役老兵。</li><li><strong>赤锤军械 (Red Hammer Armory)</strong>: <em>[原神兵阁]</em> 挂满齿轮与刀剑的武器店。铁匠不仅打铁，还精通铆接技术。</li><li><strong>灵枢堂 (Spirit Pivot Hall)</strong>: <em>[原奇珍阁]</em> 出售炼金药剂与机械零件。店主声称自己是神农氏的后裔（虽然戴着防毒面具）。</li><li><strong>铜管酒肆 (Brass Pipe Pub)</strong>: <em>[原醉仙楼]</em> 墙壁上布满黄铜管道的酒馆，招牌是&quot;机油黑啤&quot;（其实是黑豆发酵酒）。</li><li><strong>旅人驿站 (Traveler&#39;s Post)</strong>: <em>[原悦来客栈]</em> 提供标准胶囊房与热水澡。</li><li><strong>天工剑盟·驻地 (Tiangong Alliance Outpost)</strong>: <em>[原凌云剑派]</em> 位于高处的守备据点。这是一个信奉&quot;以械入道&quot;的组织，负责维护青铜炼炉的稳定。</li></ul></li></ul><h3 id="_1-2-月白重工区-moonwhite-industrial-zone" tabindex="-1">1.2 月白重工区 (Moonwhite Industrial Zone) <a class="header-anchor" href="#_1-2-月白重工区-moonwhite-industrial-zone" aria-label="Permalink to &quot;1.2 月白重工区 (Moonwhite Industrial Zone)&quot;">​</a></h3><ul><li><strong>Scene_ID</strong>: <code>Town_MoonWhite</code></li><li><strong>描述</strong>: 位于苍狼山脉另一侧的工业重镇，巨大的齿轮城墙阻挡着荒原的妖兽。</li></ul><hr><h2 id="_2-场景拓扑结构-connection-topology" tabindex="-1">2. 场景拓扑结构 (Connection Topology) <a class="header-anchor" href="#_2-场景拓扑结构-connection-topology" aria-label="Permalink to &quot;2. 场景拓扑结构 (Connection Topology)&quot;">​</a></h2><p>根据<a href="./../../00_世界观与架构/世界架构.html">世界架构与场景连接</a>的设计，本章场景连接关系如下：</p>',10)),(e(),s(c,null,{default:o(()=>[g(a,{id:"mermaid-83",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20Town_CyanFurnace%5B%E9%9D%92%E7%82%89%E9%95%87%5D%20%3C--%3E%20Road_Cyan_East%5B%E9%9D%92%E7%82%89%E9%95%87%E4%B8%9C%E9%83%8A%E5%BA%9F%E5%A2%9F%5D%0A%20%20%20%20Road_Cyan_East%20%3C--%3E%20Dungeon_WolfMine%5B%E8%8B%8D%E7%8B%BC%E7%9F%BF%E5%B1%B1%5D%0A%20%20%20%20Dungeon_WolfMine%20%3C--%3E%20Road_Moon_West%5B%E6%9C%88%E7%99%BD%E8%A5%BF%E4%BE%A7%E8%BF%90%E8%BE%93%E7%BA%BF%5D%0A%20%20%20%20Road_Moon_West%20%3C--%3E%20Town_MoonWhite%5B%E6%9C%88%E7%99%BD%E9%87%8D%E5%B7%A5%E5%8C%BA%5D%0A%20%20%20%20%0A%20%20%20%20Road_Cyan_East%20%3C--%3E%20Dungeon_CorrodedCave%5B%E8%9A%80%E9%AA%A8%E5%9C%B0%E7%A9%B4%20(%E6%94%AF%E7%BA%BF)%5D%0A%20%20%20%20Dungeon_WolfMine%20%3C--%3E%20Dungeon_FallenDragon%5B%E5%9D%A0%E9%BE%99%E8%B0%B7%20(%E9%AB%98%E9%9A%BE%E5%8C%BA)%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=n('<h3 id="_2-1-详细连接配置-connection-detail" tabindex="-1">2.1 详细连接配置 (Connection Detail) <a class="header-anchor" href="#_2-1-详细连接配置-connection-detail" aria-label="Permalink to &quot;2.1 详细连接配置 (Connection Detail)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">当前场景 (Current)</th><th style="text-align:left;">出口 (Portal)</th><th style="text-align:left;">目标场景 (Target)</th><th style="text-align:left;">入口 (Target Spawn)</th><th style="text-align:left;">备注</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Town_CyanFurnace</strong></td><td style="text-align:left;"><code>Portal_East</code></td><td style="text-align:left;"><code>Road_Cyan_East</code></td><td style="text-align:left;"><code>Spawn_West</code></td><td style="text-align:left;">出城，路边堆满工业废料</td></tr><tr><td style="text-align:left;"><strong>Road_Cyan_East</strong></td><td style="text-align:left;"><code>Portal_West</code></td><td style="text-align:left;"><code>Town_CyanFurnace</code></td><td style="text-align:left;"><code>Spawn_East</code></td><td style="text-align:left;">回城</td></tr><tr><td style="text-align:left;"><strong>Road_Cyan_East</strong></td><td style="text-align:left;"><code>Portal_North</code></td><td style="text-align:left;"><code>Dungeon_WolfMine</code></td><td style="text-align:left;"><code>Spawn_South</code></td><td style="text-align:left;">进入矿山，有机械狼出没</td></tr><tr><td style="text-align:left;"><strong>Road_Cyan_East</strong></td><td style="text-align:left;"><code>Portal_Hidden</code></td><td style="text-align:left;"><code>Dungeon_CorrodedCave</code></td><td style="text-align:left;"><code>Spawn_Main</code></td><td style="text-align:left;">需持有[辐射检测仪]解锁</td></tr></tbody></table><hr><h2 id="_3-场景详细设计" tabindex="-1">3. 场景详细设计 <a class="header-anchor" href="#_3-场景详细设计" aria-label="Permalink to &quot;3. 场景详细设计&quot;">​</a></h2><h3 id="苍狼矿山-dungeon-wolf-mine" tabindex="-1">苍狼矿山 (Dungeon: Wolf Mine) <a class="header-anchor" href="#苍狼矿山-dungeon-wolf-mine" aria-label="Permalink to &quot;苍狼矿山 (Dungeon: Wolf Mine)&quot;">​</a></h3><ul><li><strong>Scene_ID</strong>: <code>Dungeon_WolfMine</code></li><li><strong>类型</strong>: 迷宫/野外</li><li><strong>风格</strong>: 被废弃的露天矿坑，巨大的挖掘机残骸耸立。</li><li><strong>怪物</strong>: <strong>水银恶狼</strong> (变异生物)、<strong>枯骨义肢兵</strong> (游荡的亡灵矿工)。</li><li><strong>Boss</strong>: <strong>合金白虎·原型机</strong> (占据山顶的暴走机械兽)。</li></ul><h3 id="蚀骨地穴-dungeon-corroded-cave" tabindex="-1">蚀骨地穴 (Dungeon: Corroded Cave) <a class="header-anchor" href="#蚀骨地穴-dungeon-corroded-cave" aria-label="Permalink to &quot;蚀骨地穴 (Dungeon: Corroded Cave)&quot;">​</a></h3><ul><li><strong>Scene_ID</strong>: <code>Dungeon_CorrodedCave</code></li><li><strong>类型</strong>: 纯迷宫 (支线)</li><li><strong>特色</strong>: 地下化工管道泄漏形成的毒气沼泽。</li><li><strong>怪物</strong>: <strong>阴沟毒蛟</strong>、<strong>钢丝魔蛛</strong>。</li></ul><h3 id="坠龙谷-dungeon-fallen-dragon-valley" tabindex="-1">坠龙谷 (Dungeon: Fallen Dragon Valley) <a class="header-anchor" href="#坠龙谷-dungeon-fallen-dragon-valley" aria-label="Permalink to &quot;坠龙谷 (Dungeon: Fallen Dragon Valley)&quot;">​</a></h3><ul><li><strong>Scene_ID</strong>: <code>Dungeon_FallenDragon</code></li><li><strong>类型</strong>: 危险区域 (High Level)</li><li><strong>描述</strong>: 传说中上古龙神坠落之地，现在被高能辐射覆盖。</li><li><strong>Boss</strong>: <strong>烛九阴·零号机</strong> (深处沉睡的终极兵器)。</li></ul>',10))])}const x=l(_,[["render",u]]);export{D as __pageData,x as default};
